 t=dict(id=id,title=title,range=[p,p],focus=[p],order=p,lesson=lesson,questions=questions,mode=mode,source='课本旁注与教参阅读理解。',guide='先回到原文，再作答。',keywords=[],hints=['先看题目问的是谁、什么。','回看本段人物的动作和语言。'],evidence=[],checks=[],fields=[],points=[],answer='',explain='',reject='',role='学生独立（你做）',scoreGuide='各意义单位独立核对。客观结果不代替教师对解释的评价。')
