t=task('mark','第2段 · 姑姑为什么阻止',2,['姑姑为什么阻止“我”在饺子上做记号？'],role='教师示范（我做）',keywords=['为什么','做记号'],guide='先判断做记号会怎样改变游戏，再选原因。',
 checks=[mc('prevent','姑姑阻止“我”的主要用意是什么？',['让全家先吃完普通的饺子','让谁吃到它仍由偶然决定','让红枣饺子保持漂亮外形','让奶奶更容易找到这个饺子'],1,['文中没有规定先吃普通饺子。','记号会让人有意挑选，失去凭运气吃到的意味。','“手巧”不等于这次阻止是为了外形。','第2段没有交代“我”已经决定给奶奶。'])],
 answer='姑姑不想让“我”靠记号有意挑出幸运饺子，以免破坏凭运气吃到它的游戏规则。',explain='直接信息：姑姑阻止做记号。必要推断：有记号就能认出来并挑选，因此她是在维护游戏规则。',reject='只答“因为她不准”，是重复题目；把后文送给奶奶的行动当成第2段已知动机。',hints=['想一想：有了记号，谁吃到它还是偶然的吗？','看“偷偷”“做个记号”“却被姑姑打了手”。'],points=['说清做记号能有意挑选','把阻止与维护游戏规则联系起来'],
 oral=[['幸运饺子和普通饺子有什么不同？','它包着红枣，寄托心想事成、大吉大利的祝愿。祝愿不等于一定实现。'],['结合第2段文字和插图，说一说包饺子的基本步骤。','剁肉、备馅、和面，再把馅料包进面皮。课文没有逐项写出擀皮等细节；漫画可辅助描述，不能冒充原文。']])
t=task('grandma','第3段 · 把心意送给奶奶',3,['“我”如何表达对奶奶的爱？'],keywords=['如何','奶奶'],evidence=[ev('加入“我”的行动及原因',[3],['我赶紧把幸运饺子'],['夹到奶奶的碗里','奶奶向来最疼爱我'])],checks=[mc('motive','“我”把饺子夹给奶奶，最能说明什么？',['希望奶奶帮忙保留这只饺子','因为奶奶视力不好而帮她夹菜','让奶奶替自己检验饺子的馅料','把美好的祝愿送给疼爱自己的奶奶'],3,['文中没有保管的意思。','视力不好在下一段才说明，不能替代这里的原因。','“我”已经认出了幸运饺子。','行动和“因为”后面的原因共同体现回报关爱。'])],answer='“我”赶紧把幸运饺子夹到奶奶碗里，把美好祝愿送给一向疼爱自己的奶奶。',explain='先写怎样做，再说明这个动作表达的心意。第3段“因为”直接交代原因，不必再猜。',reject='只写“奶奶疼爱我”，只有原因，没有回答“如何”；说“我不爱吃饺子”与第1段矛盾。',hints=['“如何”先找具体行动。','看本段末句，“夹到”回答行动，“因为”回答原因。'],points=['行动准确','原因与心意相连'],oral=[['“我”怎样认出幸运饺子？','它鼓鼓的，看起来稍大些。']])
t=task('wink','第4段 · 眨眨眼的意思',4,['可以把“眨眨眼”换成“微笑”吗？有什么不一样？'],role='师生共构（我们做）',keywords=['换成','有什么不一样'],conceptNotes=[['动作传意','先想动作传递了什么，再比较换词后少了什么。']],checks=[mc('wink-effect','哪项最能说明两个动作的差别？',['眨眼较隐蔽，能传递彼此会意','微笑较隐蔽，更能避开家人注意','眨眼说明视力好，微笑说明开心','两种动作都慈爱，表达效果相同'],0,['奶奶发现了饺子，眨眼让“我”知道她明白心意。','教参指出眨眼比微笑隐蔽。','“视力不好”与动作表达的心意不是同一问题。','只看到共同的慈爱，漏掉会意与隐蔽。'])],answer='不宜换。“眨眨眼”比“微笑”隐蔽，不容易被其他人发现，还能表现奶奶和“我”之间的默契；“微笑”主要表示慈爱或高兴，不能同样具体地传达这种会意。',explain='默契（tacit understanding）：不用明说，彼此也明白。奶奶的动作与前文“还是发现了”相连。',reject='只答“不能，因为眨眼比较生动”；把眨眼解释为眼睛不舒服。',hints=['先想奶奶发现了什么，想让谁明白。','比较“隐蔽”和“不说话也懂”，不要只比较高兴不高兴。'],points=['比较了两个动作','说出隐蔽或默契的具体效果'],oral=[['奶奶为什么把幸运饺子夹给妈妈？','妈妈既工作又照顾一家老小，很辛苦；奶奶希望她天天幸福快乐。']])
t=task('careful','第5段 · 姑姑细心的证据',5,['从哪里可以看出姑姑是个细心的人？'],mode='written',range=[2,5],keywords=['从哪里','细心'],guide='自己写判断，再找两处行为说明。可回看第2段。',evidence=[ev('加入两处具体行为，可连续加入多句',[2,5],['做个记号','马上就发现'],['做个记号','马上就发现'])],fields=[field('character','你的回答','姑姑……。第2段……；第5段……。这些细节说明……。')],answer='姑姑是个细心的人。“我”想偷偷做记号时，她发现并阻止了；妈妈趁她不注意换碗，她又马上发现了幸运饺子。这说明她能留意到别人不易察觉的小动作和变化。',explain='用具体行为证明“细心”，不能只抄“姑姑是个细心的人”来证明同一句评价。',reject='只引用作者直接评价，缺少行为；用“手巧、包得漂亮”证明细心，证据不够直接。',hints=['找姑姑发现了什么。不要只重复课文给她的评价。','第2段：偷偷做记号；第5段：趁她不注意换碗。她分别有什么反应？'],points=['第2段发现并阻止记号','第5段马上发现幸运饺子','解释行为怎样体现细心'],scoreGuide='教师参考3点：两处行为各1点，解释能留意细小变化1点。各点独立给分，接受等义表达；只抄评价不给行为分。')
t=task('swap','第6段 · 偷龙转凤',6,['“偷龙转凤”是什么意思？为什么加引号？'],keywords=['是什么意思','为什么','引号'],conceptNotes=[['词的本义与语境义','先理解词本来的意思，再说清它在这一句指谁做了什么。'],['偷龙转凤','原指用欺骗的手法暗中改变事物的内容。']],checks=[mc('meaning','“偷龙转凤”在这里具体指什么？',['姑姑把红枣换成了普通馅料','妈妈和姑姑换了盛饺子的碗','姑姑趁“我”不注意把饺子给“我”','奶奶背着大家把饺子送给妈妈'],2,['原文没有换馅。','这是第5段妈妈的动作，不是本句的对象。','解释清楚“姑姑”“悄悄”“把饺子给我”。','这是第4段的情节，人物与范围不符。']),mc('quotes','这里加引号主要提醒我们什么？',['姑姑借用了别人的祝福原话','这个成语在这里是借来形容做法','家里真的发生了偷换龙凤的事','“我”认定姑姑做了欺骗家人的坏事'],1,['引号括住的是成语，不是引用祝福语。','借用“暗中改变”的意思写悄悄送祝福。','不能把成语拆成真的动物。','文中借用词语，并非谴责姑姑欺骗。'])],answer='本义：用欺骗的手法暗中改变事物的内容。文中指姑姑趁“我”不注意，偷偷把幸运饺子放到“我”的碗里。引号表示借用这个词语，形容她悄悄送来祝福的做法。',explain='解释成语要补足人物、动作和对象。这里保留“暗中改变”的意思，语境表达家人的关爱。',reject='只写字典义，没有联系姑姑与饺子；误以为姑姑做坏事；把妈妈换碗当成本句动作。',hints=['先找出引号前后是谁在做事。','第6段结尾直接说明“把幸运饺子放到了我的碗里”。'],points=['说清本义','解释本句具体动作','说明借用的作用'],oral=[['“莫名其妙”与“恍然大悟”写出了怎样的变化？','先不明白饺子怎么回到自己碗里，听姑姑的话后突然明白原因。']])
t=task('family','第7段 · 满满一碗的心意',7,['为什么一家人把“幸运饺子”传来传去？他们的家庭关系怎么样？','满满一碗的“幸运饺子”为什么加引号？'],range=[2,7],keywords=['为什么','家庭关系','引号'],checks=[mc('relationship','传来传去最能说明家人怎样相处？',['都希望把祝福送给关心的人','都认为红枣饺子吃起来不好吃','都担心收下它会给自己添麻烦','都想让爸爸最后吃到那颗红枣'],0,['每次转送都顾念对方，体现互相关爱。','第1段明确“我”喜欢幸运饺子。','文中是祝福与感激，没有怕麻烦。','给爸爸是在最后回应玩笑，不能解释前面的传递。']),mc('bowl','爸爸碗里“幸运饺子”的意思是什么？',['家人又包了许多放红枣的饺子','爸爸碗里的饺子全都特别大','姑姑原先包的那一个幸运饺子','普通饺子也寄托着家人的关爱'],3,['第2段只写其中一个包红枣。','第7段没有比较饺子的大小。','那一个已经在第6段被“我”吃到。','引号提示这里借称承载心意的普通饺子。'])],answer='大家想把美好的祝愿送给彼此，说明这个家庭关系融洽、互相关爱。爸爸碗里的饺子并非姑姑原先包红枣的那一个；普通饺子也承载家人的关爱，所以称为“幸运饺子”。',explain='读到第7段后才回顾前面的传递。第6段“我”已吃到红枣饺子，第7段大家夹的是各自碗里的饺子。',reject='认为全家嫌弃红枣饺子；认为爸爸真的不受关心；把每一个普通饺子都说成包着红枣。',hints=['把“装出”和“大家立刻”连起来读。','回想第6段谁已吃到红枣。第7段大家夹的是什么？'],points=['说清传递祝愿','关系判断有行为依据','区分原来的饺子与借称的饺子'])
t=task('thread','全文 · 线索与主题',8,['读课文，找出事物线索，理解文章主题。'],lesson=2,scope='full',range=[1,8],source='课本《巩固练习》第二题。七行内容完整保留，填写线索后再判断主题。',conceptNotes=[['事物线索','像一根线，把几件事串起来。要看什么事物连接了故事的开头、传递与结尾。'],['主题','借这些事情表达什么想法。线索是串起故事的事物，主题是作者要说的道理。']],guide='先读七行，再填线索。空格会同步显示你的选择；现在还没有核对对错。',fields=[dict(id='thread',type='select',label='本文的线索',options=['一家人的团聚','幸运饺子','年夜饭的饭碗','姑姑的祝福'],correct='幸运饺子')],checks=[mc('theme','哪项最准确地概括全文主题？',['吃到包红枣的饺子就会实现愿望','家人争取好运才会更加幸福','家人彼此关爱，开心团聚最珍贵','长辈把饺子让给孩子才能过好年'],2,['把祝愿当作保证，违背第8段。','家人把祝福送给别人，并非争夺。','第2—7段的行动和第8段的总结共同支持。','只抓部分情节，未概括全篇。'])],answer='线索：幸运饺子。主题：一家人互相关爱、关系融洽；比起谁吃到幸运饺子，一家人开开心心地团聚在一起更重要。',explain='幸运饺子连接“喜欢、包、传递、吃到、借称”的情节；亲情与团聚是这些情节表达的中心意思。',reject='把“亲情”当作本题所问的事物线索；把“幸运饺子”三个字当成主题；只因一个词反复出现就认定线索。',hints=['找能连接第1—7段几件事的具体事物。','再读第8段：作者把哪两件事比较，认为哪件更重要？'],points=['能说明线索怎样串起情节','把具体物件与中心意思分开'])
t=task('open','第8段 · 我理解的团聚',8,['结合课文内容和自己的生活经验，说说你对第8段内容的理解。'],mode='written',lesson=2,scope='full',range=[1,8],source='教参第8段理解题；书面框架为教学支架。',required=True,keywords=['结合课文内容','自己的生活经验','理解'],concept='open',guide='写一小段。解释为什么，并用自己的真实经历支持；参考答案不是唯一答案。',fields=[field('response','你的看法、理由、例子与回扣','我认为……，因为……。课文中……。我曾经……。这让我明白……。')],answer='【假设情境示范，请换成自己的真实经历】我认为一家人开心团聚比谁得到好运更重要，因为家人的关心能让人感到温暖。课文中，大家把幸运饺子送给彼此，最后全家都笑了。例如，假设一次家里的团圆饭菜式很简单，但家人一起准备食物、听彼此分享近况，仍感到温暖。这说明饭菜或好运并非最重要，彼此陪伴和关爱才使团聚有意义。',alternatives=['也可表达有依据的不同看法，例如珍惜祝福习俗的意义，同时说明它怎样帮助家人团聚。不要把参考提示中的经历当成自己的经历。'],explain='课文证据说明作者的理解，自己的具体经历支持你的看法。经历须包含事情和感受，最后解释它怎样支持观点。',reject='只写“团聚很好”，没有理由；只重述课文，没有自己的经历；编造经历套用示范；例子与团聚或关爱无关。',hints=['把“谁吃到饺子”与“一家人开心团聚”作比较，说清你怎么看。','回想一次真实的家人相处：谁做了什么，你有什么感受？这怎样证明你的看法？'],points=['有明确理解与理由','联系准确课文内容','有自己的具体经历','解释经历与观点的联系'],scoreGuide='教师参考4点：理解与理由1点，课文依据1点，个人经历1点，解释回扣1点。接受有依据的不同立场；各点独立给分，不按关键词或字数自动评分。')
t=task('sentence','第8段 · 仿写句子',8,['仿写句子。','例：吃没吃到幸运饺子并不重要，重要的是，我们一家人能够开开心心地团聚在一起。'],mode='written',lesson=2,source='课本《巩固练习》第一题。',keywords=['并不重要','重要的是'],conceptNotes=[['比较轻重','前半句放较次要的结果或形式，后半句放更值得珍惜的收获。两部分要谈同一件事。']],guide='只写一句，把两部分的关系说清楚。',fields=[field('sentence','你的句子','……并不重要，重要的是，……。')],answer='比赛有没有拿第一并不重要，重要的是，我们在准备和比赛中学会合作。',explain='前后都在谈同一场比赛，前面是名次，后面是更重视的学习收获。示范为教师拟写。',reject='前半句谈比赛，后半句突然谈晚餐；只机械套句式，没有轻重关系；用句式否定诚信或安全等必要原则。',hints=['先选一件事，再想这件事中你更重视什么。','检查前后两部分是否相关，后半句有没有说明更珍惜的意义。'],points=['句式完整通顺','前后围绕同一事情','轻重关系合理'],scoreGuide='教师参考2点：句式正确1点，前后相关且轻重合理1点。接受不同生活情境。')
SOURCES=[dict(label='中国文化网：北方年夜饭的饺子',url='https://en.chinaculture.org/a/202102/08/WS6020a52ca31024ad0baa800a.html'),dict(label='新加坡华族文化百科：捞鱼生',url='https://culturepaedia.singaporeccc.org.sg/zh/popular-culture/lohei/'),dict(label='新加坡华族文化中心：本地新年特色',url='https://singaporeccc.org.sg/zh-hans/events/what-makes-a-chinese-new-year-singaporean-jan-2023/')]
t=task('compare','查资料 · 两地过年',8,['上网查一查，然后和同学讨论：中国北方过农历新年和新加坡有什么不同。'],mode='oral',lesson=2,scope='full',range=[1,8],source='课本《巩固练习》第三题；“为什么仍重视团聚”为补充追问。',guide='两人各查一个资料入口。比较同一个方面，先说给同桌听，再展开参考。',resources=SOURCES,conceptNotes=[['比较的范围','这里比较中国北方与新加坡华人常见的农历新年习俗，不能说每个家庭都一样。']],answer='可比较年节食物：中国北方常见全家包饺子、吃饺子；新加坡华人常见一起捞鱼生并说吉祥话。食物与做法有不同，但都能寄托祝福、凝聚家人。',explain='资料只支持“常见”的习俗，不能推出“北方人不吃鱼生”或“新加坡人不吃饺子”。比较要使用同一方面，并写清来源。',reject='拿北方吃饺子与新加坡天气热比较，维度不一致；把不同习俗说成互相排斥；把所有新加坡人视为庆祝农历新年的华人。',hints=['先选“年节食物”这个方面，两人各查一地。','说出两地各吃什么、怎样一起吃，再补共同的祝愿。'],points=['两地比较同一方面','事实与来源可核对','避免“所有、一定”等扩大说法'],scoreGuide='口头讨论由教师观察，不纳入自动正确率。可选填关键词作为记录，不能以点击讲评证明已理解。',oral=[['为什么做法不同，仍值得和家人一起参与？','可联系共同参与、互相祝福、珍惜相处等作合理解释。']])
for t in L['tasks']:
 if t['id'] in ['swap','family']:t['lesson']=2
L['paragraphTasks']=['','mark','grandma','wink','careful','swap','family','open']
L['threadRows']=[['1','我喜欢吃饺子，更喜欢吃到幸运饺子时的那份喜悦。'],['2','“谁要是吃到这个幸运饺子，今年就会心想事成，大吉大利！”'],['3','我赶紧把幸运饺子夹到奶奶的碗里，因为奶奶向来最疼爱我。'],['4','她（奶奶）慈爱地对我眨眨眼，然后把幸运饺子夹到妈妈的碗里。'],['5','妈妈趁姑姑不注意，又和姑姑换了碗。姑姑是个细心的人，马上就发现了碗里的幸运饺子。'],['6','原来是姑姑“偷龙转凤”，把幸运饺子放到了我的碗里。'],['7','望着满满一碗的“幸运饺子”，爸爸笑了，一家人都笑了。']]
L['sources']=SOURCES
words=[('围坐',1,'围成一圈坐着。'),('传统',1,'一代代流传下来的习惯或做法。'),('幸运',1,'运气好；文中也寄托美好祝愿。'),('喜悦',1,'高兴、愉快。'),('往年',2,'过去的年份。'),('剁',2,'用刀向下反复用力切。'),('馅料',2,'包在饺子等食品里面的材料。'),('和',2,'这里读huó，把水加进面粉里揉拌。'),('手巧',2,'手的动作灵活，做东西细致好看。'),('心想事成',2,'心里希望的事情能够实现。'),('大吉大利',2,'非常吉利、顺利，用于祝福。'),('记号',2,'为辨认事物而做的标记。'),('亲自',3,'自己直接去做。'),('鼓鼓的',3,'向外鼓起、显得饱满的样子。'),('稍',3,'略微；一点点。'),('紧盯',3,'集中目光一直看着。'),('招呼',3,'文中指叫大家来吃饺子。'),('赶紧',3,'抓紧时间，马上行动。'),('向来',3,'一向；从过去到现在。'),('疼爱',3,'很爱护、关心。'),('视力',4,'眼睛看清东西的能力。'),('慈爱',4,'长辈对晚辈温和而充满爱。'),('儿媳妇',4,'儿子的妻子。'),('照顾',4,'关心、照料。'),('感动',4,'因别人的关爱等而内心受到触动。'),('趁',5,'利用某个时机。'),('细心',5,'能留意细小的地方。'),('感激',5,'因得到关心或帮助而感谢。'),('莫名其妙',6,'不明白其中的原因，感到奇怪。'),('疑惑',6,'心里不明白，有疑问。'),('肩膀',6,'手臂和身体相连接的上部。'),('亲切',6,'态度亲近、温和。'),('学业',6,'学习的功课和进展。'),('恍然大悟',6,'突然完全明白了。'),('偷龙转凤',6,'本指暗中用欺骗的手法改变事物内容；文中借指姑姑悄悄把幸运饺子给“我”。'),('可怜',7,'值得同情；文中爸爸是假装委屈。'),('话音刚落',7,'刚刚说完话。'),('立刻',7,'马上；没有耽搁。'),('团聚',8,'家人等聚集在一起。')]
W={w:dict(meaning=m,paragraph=p) for w,p,m in words}
